#!/usr/bin/env node
/**
 * V9 Deployment Sync Script
 *
 * Syncs deployment data from packages/contracts-core/deployments/v9-*.json
 * to the frontend config files:
 *   - apps/web/src/config/deployments.json (contract addresses)
 *   - apps/web/src/config/markets.json (market configurations)
 *
 * Usage: node sync-v9-deployments.js
 *
 * Source of Truth: packages/contracts-core/deployments/v9-{chainName}.json
 * These files are generated by Foundry deployment scripts.
 */

const fs = require('fs');
const path = require('path');

// Paths
const DEPLOYMENTS_DIR = path.resolve(__dirname, '../../../packages/contracts-core/deployments');
const FE_DEPLOYMENTS = path.resolve(__dirname, '../src/config/deployments.json');
const FE_MARKETS = path.resolve(__dirname, '../src/config/markets.json');
const CONTRACTS_DEPLOYMENTS = path.resolve(__dirname, '../../../packages/contracts-core/deployments.json');

// Chain name to network key mapping
const CHAIN_NAME_MAP = {
  'baseSepolia': 'baseSepolia',
  'monadTestnet': 'monadTestnet',
  'bnbTestnet': 'bnbTestnet',
  'megaethTestnet': 'megaethTestnet',
  'megaethFrontier': 'megaethFrontier',
};

// Market ID generation (matches existing convention)
function generateMarketId(symbol, chainName) {
  const chainSuffix = chainName === 'baseSepolia' ? 'base' : chainName.replace('Testnet', '').toLowerCase();
  return `${symbol.toLowerCase()}-${chainSuffix}`;
}

// Find existing market by address and chainId (handles ID variations)
function findExistingMarket(markets, address, chainId) {
  const normalizedAddr = address.toLowerCase();
  return markets.findIndex(m =>
    m.address.toLowerCase() === normalizedAddr && m.chainId === chainId
  );
}

// Market category detection
function detectCategory(name) {
  const lower = name.toLowerCase();
  if (lower.includes('btc') || lower.includes('eth') || lower.includes('crypto')) return 'crypto';
  if (lower.includes('alien') || lower.includes('science')) return 'science';
  if (lower.includes('election') || lower.includes('president') || lower.includes('vote')) return 'politics';
  return 'general';
}

async function main() {
  console.log('🔄 V9 Deployment Sync');
  console.log('━'.repeat(50));

  // 1. Find all v9 deployment files
  const files = fs.readdirSync(DEPLOYMENTS_DIR).filter(f => f.startsWith('v9-') && f.endsWith('.json'));

  if (files.length === 0) {
    console.error('❌ No v9-*.json files found in', DEPLOYMENTS_DIR);
    process.exit(1);
  }

  console.log(`📁 Found ${files.length} deployment file(s): ${files.join(', ')}`);

  // 2. Load existing configs
  let feDeployments = { version: '9.9.0', networks: {} };
  let feMarkets = { version: '9.9.0', markets: [] };

  if (fs.existsSync(FE_DEPLOYMENTS)) {
    feDeployments = JSON.parse(fs.readFileSync(FE_DEPLOYMENTS, 'utf8'));
  }
  if (fs.existsSync(FE_MARKETS)) {
    feMarkets = JSON.parse(fs.readFileSync(FE_MARKETS, 'utf8'));
  }

  // Track changes
  const changes = { contracts: [], markets: [] };

  // 3. Process each deployment file
  for (const file of files) {
    const filePath = path.join(DEPLOYMENTS_DIR, file);
    const deployment = JSON.parse(fs.readFileSync(filePath, 'utf8'));

    const chainName = deployment.chainName;
    const chainId = deployment.chainId;
    const networkKey = CHAIN_NAME_MAP[chainName] || chainName;

    console.log(`\n📦 Processing ${chainName} (chainId: ${chainId})`);

    // 3a. Sync contracts
    const oldContracts = feDeployments.networks[networkKey]?.contracts || {};
    const newContracts = deployment.contracts || {};

    // Check for changes
    for (const [name, addr] of Object.entries(newContracts)) {
      if (oldContracts[name] !== addr) {
        changes.contracts.push({ network: networkKey, contract: name, old: oldContracts[name], new: addr });
        console.log(`   📝 ${name}: ${oldContracts[name] || '(new)'} → ${addr}`);
      }
    }

    // Update contracts
    feDeployments.networks[networkKey] = {
      chainId,
      contracts: newContracts,
    };

    // 3b. Sync markets
    const deployedMarkets = deployment.markets || [];

    for (const market of deployedMarkets) {
      const marketId = generateMarketId(market.symbol, chainName);
      // Find by address+chainId first (handles ID naming variations)
      let existingIdx = findExistingMarket(feMarkets.markets, market.address, chainId);

      const marketConfig = {
        id: marketId,
        chainId,
        address: market.address.toLowerCase(),
        contractAddress: market.address.toLowerCase(),
        name: market.name,
        symbol: market.symbol,
        yesToken: market.yesToken,
        noToken: market.noToken,
        description: market.description || `Market for ${market.name}`,
        category: detectCategory(market.name),
        featured: true,
        imageUrl: null,
        outcomes: ['YES', 'NO'],
        version: 'v9',
        isGraduated: market.isGraduated || false,
      };

      if (existingIdx >= 0) {
        const existing = feMarkets.markets[existingIdx];
        // Preserve description if existing has a better one
        if (existing.description && !existing.description.startsWith('Market for ')) {
          marketConfig.description = existing.description;
        }
        // Check for differences
        const diffs = [];
        if (existing.id !== marketConfig.id) diffs.push(`id (${existing.id} -> ${marketConfig.id})`);
        if (existing.yesToken !== marketConfig.yesToken) diffs.push('yesToken');
        if (existing.noToken !== marketConfig.noToken) diffs.push('noToken');
        if (existing.isGraduated !== marketConfig.isGraduated) diffs.push('isGraduated');

        if (diffs.length > 0) {
          changes.markets.push({ id: marketId, changes: diffs });
          console.log(`   📝 Market ${marketId}: updated ${diffs.join(', ')}`);
        }
        feMarkets.markets[existingIdx] = marketConfig;
      } else {
        changes.markets.push({ id: marketId, changes: ['new'] });
        console.log(`   ➕ Market ${marketId}: added`);
        feMarkets.markets.push(marketConfig);
      }
    }
  }

  // Remove duplicate markets (same address+chainId, keep first occurrence by new canonical ID)
  const seen = new Map();
  feMarkets.markets = feMarkets.markets.filter(m => {
    const key = `${m.chainId}:${m.address.toLowerCase()}`;
    if (seen.has(key)) {
      console.log(`   🗑️  Removing duplicate: ${m.id}`);
      return false;
    }
    seen.set(key, true);
    return true;
  });

  // 4. Update version timestamps
  const version = `9.9.${Date.now() % 1000}`;
  feDeployments.version = version;
  feMarkets.version = version;

  // 5. Write updated configs
  console.log('\n💾 Writing updated configs...');

  fs.writeFileSync(FE_DEPLOYMENTS, JSON.stringify(feDeployments, null, 2) + '\n');
  console.log(`   ✅ ${FE_DEPLOYMENTS}`);

  fs.writeFileSync(FE_MARKETS, JSON.stringify(feMarkets, null, 2) + '\n');
  console.log(`   ✅ ${FE_MARKETS}`);

  // 6. Also sync to contracts package
  fs.writeFileSync(CONTRACTS_DEPLOYMENTS, JSON.stringify(feDeployments, null, 2) + '\n');
  console.log(`   ✅ ${CONTRACTS_DEPLOYMENTS}`);

  // 7. Summary
  console.log('\n' + '━'.repeat(50));
  if (changes.contracts.length === 0 && changes.markets.length === 0) {
    console.log('✅ All configs already in sync!');
  } else {
    console.log(`✅ Sync complete! Changes:`);
    console.log(`   - ${changes.contracts.length} contract address(es) updated`);
    console.log(`   - ${changes.markets.length} market(s) updated`);
    console.log('\n⚠️  Remember to:');
    console.log('   1. Review the changes');
    console.log('   2. Test the frontend');
    console.log('   3. Commit the updated config files');
  }
}

main().catch(err => {
  console.error('❌ Sync failed:', err);
  process.exit(1);
});
